fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8> {
    // We assume `min < max` as per the problem statement.
    a.into_iter()
     .map(|x| {
         if x < min {
             min
         } else if x > max {
             max
         } else {
             x
         }
     })
     .collect()
}

